window.HOEREN_TESTS[55] = {"id":"beim-baecker","name":"Beim Bäcker","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: Unsere Bäckerei hat ab Montag neue Öffnungszeiten. Statt 6 bis 18 Uhr nun 5 Uhr 30 bis 19 Uhr, also länger am Abend. Wir öffnen morgens um 5 Uhr 30, nicht um 6 Uhr. Sonntags 7 bis 12 Uhr wie immer. Frische Brötchen gibt es jeden Morgen ab 6 Uhr. Wir freuen uns auf euren Besuch!","gender":"f","q":"Wann öffnet die Bäckerei jetzt morgens?","opts":["5 Uhr 30.","6 Uhr.","7 Uhr."],"correct":0},{"transcript":"Hallo Mama, hier ist Anna. Ich gehe zum Bäcker, was brauchen wir? Brot ist alle, Brötchen auch, also Brot und Brötchen definitiv. Nur Kuchen brauchen wir nicht unbedingt, und nur Brot reicht auch nicht. Vielleicht noch ein Kuchen für morgen, Geburtstag von Tante. Sage bitte schnell Bescheid, sonst entscheide ich selbst.","gender":"f","q":"Was braucht Anna definitiv?","opts":["Nur Kuchen.","Brot und Brötchen.","Nur Brot."],"correct":1},{"transcript":"Achtung Kunden: Unsere neue Roggen-Brot-Sorte ist heute zur Verkostung im Laden. Sie kostet 3 Euro 50 statt 4 Euro. Auch das Mehrkorn-Brot ist im Angebot, 2 Euro 80. Vollkornbrot ist diese Woche leider nicht im Angebot. Beim Bezahlen bitte sagen, dass die Ware aus dem Angebot ist. Guten Appetit und bis bald!","gender":"m","q":"Welches Brot ist nicht im Angebot?","opts":["Roggen.","Mehrkorn.","Vollkorn."],"correct":2},{"transcript":"Hi Markus, hier ist Lisa. Also, ich brauche eine Geburtstags-Torte für morgen. Ich habe sie gerade beim Bäcker bestellt, du musst sie nicht bestellen und nicht backen. Schokolade mit Erdbeeren, 30 Euro, groß für 10 Personen. Holst du sie um 16 Uhr ab? Ich kann nicht. Adresse: Bäckerei Sonne, Marktstraße 5. Danke dir!","gender":"f","q":"Was muss Markus tun?","opts":["Torte abholen.","Torte bestellen.","Torte backen."],"correct":0},{"transcript":"Liebe Kunden: Unsere Brötchen sind heute leider knapp. Bitte nicht mehr als 6 pro Person nehmen, nicht 10 und nicht unbegrenzt, viele Kunden möchten welche. Die nächste Lieferung kommt um 14 Uhr, dann wieder volles Sortiment. Wir entschuldigen uns für die Unannehmlichkeiten. Vielen Dank für Ihr Verständnis und bis später!","gender":"f","q":"Wie viele Brötchen pro Person?","opts":["Maximal 10.","Maximal 6.","Unbegrenzt."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kauft was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Bäcker an der Ecke macht heute früher auf."},{"speaker":"Lisa","gender":"f","text":"Das passt perfekt. Ich wollte vor der Arbeit noch etwas Süßes holen."},{"speaker":"Lukas","gender":"m","text":"Ich hole zwei warme Brezeln. Das Salz darauf mag ich am frühen Morgen."},{"speaker":"Lisa","gender":"f","text":"Ich nehme Croissants mit. Sie sind weich und passen gut zum Kaffee."},{"speaker":"Lukas","gender":"m","text":"Sollen wir noch Donuts mitnehmen?"},{"speaker":"Lisa","gender":"f","text":"Nein. Donuts gibt es hier nicht in der Auslage."},{"speaker":"Lukas","gender":"m","text":"Tom isst abends wenig und braucht etwas Kräftiges für die Tasche."},{"speaker":"Lisa","gender":"f","text":"Tom nimmt ein Vollkornbrot mit. Die Scheiben machen lange satt."},{"speaker":"Lukas","gender":"m","text":"Sara bekommt am Sonntag Besuch von ihrer Tante."},{"speaker":"Lisa","gender":"f","text":"Sara lässt einen Käsekuchen einpacken. Der kommt frisch und warm aus dem Ofen."},{"speaker":"Lukas","gender":"m","text":"Nehmen wir ein Schwarzbrot für den Abend mit?"},{"speaker":"Lisa","gender":"f","text":"Nein. Ein Schwarzbrot nehmen wir nicht. Das schmeckt uns zu herb."},{"speaker":"Lukas","gender":"m","text":"Tim kommt vom Nachtdienst und will etwas mit roter Marmelade."},{"speaker":"Lisa","gender":"f","text":"Tim bestellt Berliner. Die Füllung ist heute rot und richtig süß."},{"speaker":"Lukas","gender":"m","text":"Dann stelle ich mich jetzt vorn an die Theke."},{"speaker":"Lisa","gender":"f","text":"Ich halte die Papiertüte schon weit offen."}],"options":[{"letter":"a","text":"Vollkornbrot"},{"letter":"b","text":"Käsekuchen"},{"letter":"c","text":"Schwarzbrot"},{"letter":"d","text":"Apfelstrudel"},{"letter":"e","text":"Berliner"},{"letter":"f","text":"Croissants"},{"letter":"g","text":"Brezeln"},{"letter":"h","text":"Donuts"},{"letter":"i","text":"Brötchen"}],"items":[{"person":"Lukas","correct":"g"},{"person":"Lisa","correct":"f"},{"person":"Tom","correct":"a"},{"person":"Sara","correct":"b"},{"person":"Tim","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, fünf Brötchen bitte. Welche Sorten haben Sie noch frisch?"},{"speaker":"Bäckerin","gender":"f","text":"Normale und Körner-Brötchen. Wollen Sie drei Körner, zwei, oder alle fünf Körner?"},{"speaker":"Kundin","gender":"f","text":"Nicht drei Körner und nicht fünf. Drei normal und zwei Körner bitte."},{"speaker":"Bäckerin","gender":"f","text":"Also zwei Körner-Brötchen und drei normale. Das macht 1 Euro 80 bitte."},{"speaker":"Kundin","gender":"f","text":"Genau, zwei Körner. Hier das Geld, schönen Tag noch!"}],"q":"Wie viele Körner-Brötchen?","opts":["Drei.","Fünf.","Zwei."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, haben Sie noch Mohnstreusel? Ich wollte ein Stück für den Kaffee."},{"speaker":"Verkäuferin","gender":"f","text":"Leider ausverkauft. Wir haben noch Käsekuchen oder Schwarzwälder Kirsch."},{"speaker":"Kunde","gender":"m","text":"Mohnstreusel ist weg, Käsekuchen esse ich oft. Dann Schwarzwälder Kirsch bitte."},{"speaker":"Verkäuferin","gender":"f","text":"Ein Stück Schwarzwälder Kirsch, 3 Euro 50. Soll ich es einpacken?"},{"speaker":"Kunde","gender":"m","text":"Ja, bitte einpacken. Danke, dann nehme ich den Kirsch und keinen Käsekuchen."}],"q":"Welcher Kuchen?","opts":["Schwarzwälder Kirsch.","Käsekuchen.","Mohnstreusel."],"correct":0},{"lines":[{"speaker":"Mutter","gender":"f","text":"Guten Tag, können wir eine Geburtstagstorte bestellen, nicht nur Brot oder Brötchen?"},{"speaker":"Bäcker","gender":"m","text":"Klar, eine Torte. Welches Motiv soll darauf, und für wie viele Personen?"},{"speaker":"Mutter","gender":"f","text":"Mit Dinosauriern, für meinen Sohn. Brot und Brötchen hole ich extra, heute nur die Torte."},{"speaker":"Bäcker","gender":"m","text":"Kein Problem. Welche Größe darf es sein, für wie viele Kinder?"},{"speaker":"Mutter","gender":"f","text":"Für 10 Kinder bitte. Kann ich die Torte am Samstag um 11 Uhr abholen?"}],"q":"Was bestellt sie?","opts":["Brot.","Geburtstagstorte.","Brötchen."],"correct":1},{"lines":[{"speaker":"Lehrling","gender":"m","text":"Meister, wann muss ich morgen kommen? Um 4 Uhr, um 6 Uhr oder erst um 8 Uhr?"},{"speaker":"Bäckermeister","gender":"m","text":"Um 4 Uhr, nicht um 6 und nicht um 8. Der Teig braucht Zeit."},{"speaker":"Lehrling","gender":"m","text":"So früh? Um 8 Uhr ist besser für mich, aber ich verstehe. Die Brötchen müssen fertig sein."},{"speaker":"Bäckermeister","gender":"m","text":"Genau, die Brötchen müssen um 6 Uhr fertig sein. Deshalb beginnst du um 4."},{"speaker":"Lehrling","gender":"m","text":"Okay, dann um 4 Uhr. Ich stelle zwei Wecker, versprochen!"}],"q":"Wann beginnt der Lehrling?","opts":["4 Uhr.","6 Uhr.","8 Uhr."],"correct":0},{"lines":[{"speaker":"Vater","gender":"m","text":"Klein-Lisa, was möchtest du vom Bäcker? Schoko-Brötchen, Apfel-Tasche oder gar nichts?"},{"speaker":"Lisa","gender":"f","text":"Ein Schoko-Brötchen bitte! Das mit der Schokolade innen, das mag ich."},{"speaker":"Vater","gender":"m","text":"Schon zwei Schoko-Brötchen heute. Nichts kaufen geht auch nicht, du hast Hunger. Nimm lieber einen Apfel."},{"speaker":"Lisa","gender":"f","text":"Okay, dann eine Apfel-Tasche? Die ist süß, aber mit Obst, ja?"},{"speaker":"Vater","gender":"m","text":"Gut, eine Apfel-Tasche, kein Schoko-Brötchen. Hier, zum Essen auf der Bank."}],"q":"Was bekommt Lisa?","opts":["Schoko-Brötchen.","Nichts.","Apfel-Tasche."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Bauer, einem Bäckermeister. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Bauer, Sie haben Ihre Bäckerei seit 25 Jahren. Wie sind Sie Bäcker geworden?"},{"speaker":"Bauer","gender":"m","text":"Mein Vater war auch Bäcker — Familie-Tradition. Eigentlich wollte ich was anderes machen, Architekt vielleicht. Aber Vater wurde krank, ich übernahm. Erst widerwillig, jetzt liebe ich es. Bäcker bin ich aus Leidenschaft."},{"speaker":"Reporterin","gender":"f","text":"Wie ist Ihr Tag?"},{"speaker":"Bauer","gender":"m","text":"Beginne um 3 Uhr morgens — Teig vorbereiten, Ofen heizen. Brötchen fertig um 6 Uhr, dann Verkauf. Mittags Pause, nachmittags Kuchen und Torten. Abends früh ins Bett, weil morgens früh raus. Hart, aber zufriedenstellend."},{"speaker":"Reporterin","gender":"f","text":"Was sind Ihre Spezialitäten?"},{"speaker":"Bauer","gender":"m","text":"Mein Roggen-Sauerteig-Brot ist berühmt — alte Familien-Rezept. Auch unsere Hochzeitstorten — alle drei Wochen kommt ein Brautpaar. Standard-Brötchen mache ich auch, aber Stolz sind die Spezialitäten."},{"speaker":"Reporterin","gender":"f","text":"Wie ist die Konkurrenz heute?"},{"speaker":"Bauer","gender":"m","text":"Schwer, discount-Bäckereien in Supermärkten — billiger, aber Qualität schlechter. Viele Kunden wählen Preis statt Qualität. Aber treue Kunden bleiben — wer Qualität kennt, kauft bei mir. Schwer, mit Familie zu konkurrieren wegen Zeit."},{"speaker":"Reporterin","gender":"f","text":"Hat Ihr Sohn Interesse?"},{"speaker":"Bauer","gender":"m","text":"Mein Sohn studiert Medizin — wollte er nicht übernehmen. Schade, aber sein Leben. Vielleicht meine Enkelin? Sie liebt schon das Backen. Wer weiß, vielleicht Familie-Tradition geht weiter."}],"items":[{"q":"Er beginnt seinen Arbeitstag um 6 Uhr morgens.","correct":"nein"},{"q":"Herr Bauer wollte ursprünglich Architekt werden.","correct":"ja"},{"q":"Sein Roggen-Sauerteig-Brot ist eine Spezialität.","correct":"ja"},{"q":"Discount-Bäckereien haben bessere Qualität als seine Bäckerei.","correct":"nein"},{"q":"Sein Sohn wird die Bäckerei übernehmen.","correct":"nein"}]}]};
